\u005a\u0048\u0049\u007b\u0036\u004b\u006c\u003b\u0042\u0071\u0059\u0053\u007a\u005e\u0067\u0059\u0036\u0037\u0065\u003c\u0022\u0053\u0058\u004e\u0050\u003f\u004b\u007b\u0078\u004d\u0040\u0060\u0034\u0030\u0079\u0021\u002b\u002c\u004a\u002c\u0024\u004c\u003f\u005d\u0072\u0063\u0044\u002f\u0074\u007e\u0054\u0052\u006a\u0052\u0041\u0040\u0024\u0047\u0071\u004e\u0026\u0068\u0075\u0067\u0056\u004b\u005d\u0030\u0033\u002c\u0050\u002b\u0056\u003d\u004b\u005e\u0077\u0077\u0063\u003a\u0073\u0057\u0068\u0048\u0036\u002b\u005b\u0024\u007a\u0059\u0059\u0075\u0075\u0078\u0024\u002f\u0048\u0060\u007d\u0024\u002b\u0070\u0056\u0043\u006f\u0051\u0057\u0076\u0021\u0024\u0064\u0050\u0069\u0070\u0072\u0070\u0050\u0068\u0039\u0058\u007d\u004a\u006a\u0024\u003c\u002c\u002e\u0041\u0079\u0063\u0048\u0025\u002b\u0029\u0024\u0044\u0078\u0038\u003f\u0073\u007d\u0030\u004d\u004f\u007b\u005e\u0043\u0024\u0024\u0055\u0055\u0030\u006b\u0045\u0024\u0068\u0034\u0051\u0059\u0024\u0071\u0039\u0071\u0047\u0062\u0034\u004d\u0048\u005b\u0052\u0036\u002c\u0044\u0024\u0053\u0031\u0062\u0063\u003f\u0045\u002e\u0039\u0051\u003d\u002c\u0052\u003a\u0077\u0064\u006c\u0022\u0030\u0028\u004e\u0052\u0043\u003f\u0030\u0024\u0058\u0021\u0055\u0052\u004e\u0036\u002e\u0043\u0023\u0032\u006b\u003e\u0022\u0071\u007e\u007c\u006c\u005e\u005e\u003d\u0046\u0052\u006a\u0059\u0032\u0052\u0030\u004d\u0031\u005b\u0051\u007e\u0024\u006e\u0021\u0074\u0035\u0078\u004b\u0075\u0064\u0043\u0023\u0053\u0059\u0028\u007c\u0031\u0063\u003d\u0034\u0057\u0056\u003d\u0048\u002c\u004a\u0029\u0024\u0037\u0052\u0040\u002b\u0029\u0029\u002c\u0079\u002b\u0068\u0035\u0043\u0024\u0030\u004e\u005e\u002a\u0062\u0055\u003c\u007b\u0036\u0057\u004b\u0067\u0050\u0029\u0032\u0042\u0062\u0060\u0078\u0074\u005a\u003e\u006a\u002e\u0077\u006f\u0079\u0041\u0052\u002e\u0057\u0060\u0044\u0062\u0057\u0040\u0050\u0037\u006a\u0052\u0046\u0077\u002c\u0032\u0053\u0057\u004b\u002f\u0057\u002f\u005a\u005a\u0023\u004f\u007b\u0079\u006e\u0036\u0074\u0059\u005a\u003e\u0065\u0055\u0077\u0030\u0057\u0031\u0069\u0070\u003c\u0038\u006f\u004a\u0055\u004f\u0075\u0057\u0077\u0068\u0065\u0074\u0029\u006f\u0064\u0045\u0051\u007d\u0057\u0021\u0022\u0077\u007b\u0037\u005e\u004a\u0041\u0045\u0023\u0057\u0041\u0052\u0028\u005e\u003e\u004d\u006d\u005d\u0077\u0055\u0076\u006d\u0057\u002e\u0057\u0044\u0066\u0048\u0078\u0041\u0078\u0024\u0052\u004c\u005e\u007e\u006e\u0064\u0060\u002e\u0047\u0058\u005e\u004b\u006f\u0076\u0037\u0070\u0034\u0058\u0037\u007c\u004a\u0068\u003d\u007a\u004b\u0028\u0070\u0036\u0057\u0044\u003c\u0028\u0022\u0024\u0037\u003f\u0025\u0024\u0075\u0050\u0078\u0028\u0058\u004e\u0036\u007b\u005b\u0052\u0033\u004e\u0060\u0026\u0062\u0034\u0038\u005b\u0074\u0057\u0076\u005f\u0022\u003b\u0037\u0075\u0065\u0026\u0077\u0034\u0072\u005d\u0030\u004b\u002e\u007a\u002e\u0060\u005b\u0052\u0035\u0022\u004f\u004b\u006c\u0031\u006a\u0075\u004c\u0052\u0077\u002e\u0031\u0067\u0065\u0024\u0032\u0046\u0071\u0067\u0021\u0073\u0074\u0041\u0049\u0075\u004b\u0070\u006a\u0077\u0055\u006d\u003a\u0048\u0079\u0042\u0053\u0051\u0023\u002c\u0028\u004b\u003e\u005d\u0038\u0066\u0078\u0044\u0047\u003c\u006a\u003e\u0070\u004b\u003a\u0073\u0049\u005b\u0044\u002a\u0068\u0063\u006a\u0067\u0061\u0074\u0057\u0045\u0077\u0035\u0041\u0058\u0068\u0023\u0047\u002e\u0039\u003b\u0056\u0023\u0053\u0052\u004b\u005d\u0046\u006c\u0039\u004b\u0051\u0077\u006c\u004a\u0031\u0030\u0043\u0059\u0061\u0022\u0039\u004b\u005a\u002b\u006f\u0029\u0032\u0067\u0074\u0030\u0051\u0062\u004f\u002b\u0034\u0024\u006e\u0040\u0022\u0073\u0052\u0055\u002e\u006a\u0024\u0034\u005b\u0063\u003a\u0079\u0042\u0041\u0077\u002e\u0054\u0062\u004b\u0077\u005f\u0075\u0056\u006c\u0061\u003d\u0024\u0066\u005a\u0065\u0040\u004a\u0061\u0042\u0076\u0048\u0060\u005b\u0038\u0028\u0074\u0076\u0052\u0073\u002f\u0057\u0055\u0064\u0033\u0058\u0047\u0034\u0030\u0057\u005f\u0043\u0069\u006b\u0076\u0054\u002f\u0079\u0022\u002a\u005e\u0024\u006a\u0061\u005a\u0056\u004a\u004d\u0041\u0045\u006e\u0039\u0074\u0074\u003b\u0069\u0061\u0060\u0023\u0026\u0032\u0066\u0049\u007a\u005d\u0021\u0031\u0049\u0076\u007c\u004b\u0061\u0052\u0032\u0052\u0023\u004b\u006e\u003e\u003b\u004a\u0039\u0039\u0025\u003a\u0074\u006f\u004a\u003c\u0073\u0043\u0031\u0059\u007d\u006e\u003f\u006d\u002f\u005d\u004a\u007a\u0038\u006b\u0036\u0077\u007b\u005b\u0030\u0030\u002c\u0026\u0022\u006c\u0035\u0060\u0022\u0025\u002b\u0064\u0032\u005f\u0050\u005a\u0047\u003d\u007e\u0056\u0079\u0062\u0034\u004e\u0063\u0075\u002e\u002e\u0021\u0065\u0079\u0035\u0058\u0068\u0070\u0043\u0033\u004c\u002a\u0074\u0041\u002e\u006b\u002e\u0072\u0064\u0060\u003c\u0056\u0075\u0056\u0077\u0049\u0052\u003e\u0069\u0061\u0066\u0073\u0074\u006e\u0037\u005e\u0042\u0048\u0041\u0045\u006b\u004b\u0061\u0021\u0076\u0056\u006a\u004d\u0057\u0030\u0049\u0070\u0072\u003e\u0065\u0061\u003d\u0068\u0060\u005d\u006e\u005e\u007b\u0024\u0033\u0063\u0068\u0052\u0062\u0051\u0035\u004f\u0061\u0077\u0031\u0072\u0048\u003a\u0026\u006c\u0051\u0064\u0070\u0079\u0039\u002e\u0066\u003a\u002f\u005d\u007b\u0073\u0035\u0042\u0063\u0039\u0057\u0072\u0052\u0073\u003c\u0038\u0021\u003f\u0026\u0041\u0040\u0054\u003d\u0065\u0076\u0049\u006c\u0028\u0056\u005e\u002f\u0066\u0070\u0045\u0075\u0051\u0049\u0072\u004a\u004e\u004b\u0051\u003e\u003f\u0078\u0053\u0042\u0038\u004a\u0045\u0036\u0038\u0026\u0060\u006c\u0021\u0055\u0049\u0056\u0074\u0077\u004a\u0048\u003b\u005e\u002f\u0048\u0073\u0040\u007d\u0041\u004d\u0050\u0072\u003f\u0073\u0026\u0058\u0068\u0033\u0044\u006f\u0039\u0054\u002f\u0040\u0064\u003c\u0037\u0068\u005e\u005f\u003f\u0026\u005b\u0026\u004f\u003b\u0071\u0032\u003b\u006a\u0026\u0055\u007a\u0051\u0022\u006b\u0031\u006d\u006d\u0073\u005e\u0025\u0040\u004f\u0031\u004b\u003c\u0051\u006c\u0050\u0067\u0041\u004e\u007c\u0024\u0077\u0054\u002f\u0040\u0065\u007a\u003b\u0041\u0077\u0071\u0066\u003c\u0040\u007c\u0024\u0074\u0054\u0067\u0044\u0052\u0056\u004d\u006e\u003e\u0069\u0070\u0066\u006b\u0064\u003a\u0043\u002e\u0033\u0047\u005a\u0037\u0056\u0073\u004e\u0029\u003f\u0055\u0061\u007c\u006a\u005e\u0077\u004c\u006e\u0025\u0052\u004a\u0054\u003d\u0057\u0071\u006e\u0055\u004d\u0044\u0061\u002f\u0061\u0045\u0029\u004b\u0031\u006a\u0038\u002a\u0033\u0033\u006d\u0062\u0031\u006f\u0054\u0030\u0072\u007b\u004b\u006b\u007b\u0043\u0032\u002f\u0041\u003b\u0043\u004a\u004c\u0064\u007a\u007c\u0057\u0061\u0023\u0065\u0045\u0051\u0023\u0069\u0034\u0040\u004b\u006b\u0052\u0075\u0067\u0064\u0023\u0059\u0073\u0068\u0029\u006d\u0025\u006c\u0055\u0066\u0033\u0056\u0067\u002f\u0067\u0069\u0033\u0060\u002b\u0061\u0076\u0078\u0061\u0043\u0032\u006f\u0043\u005e\u004e\u0023\u004d\u006a\u0037\u0050\u006b\u0059\u0068\u0038\u0051\u003c\u003b\u0045\u005e\u006c\u0037\u0073\u0038\u0071\u0061\u003a\u0069\u0032\u0038\u0060\u0070\u0075\u0052\u0065\u002c\u0023\u0066\u0072\u0045\u002e\u004f\u002a\u006d\u004d\u002c\u005e\u0037\u0053\u0076\u0028\u002f\u0074\u0057\u0045\u002e\u004f\u002a\u007e\u003c\u007d\u0022\u006c\u0049\u003b\u004e\u005f\u006d\u0028\u0074\u0036\u0068\u0042\u0038\u0065\u0066\u0038\u0037\u004e\u006c\u007b\u002e\u0074\u0047\u0062\u0079\u002a\u002f\u0060\u0043\u0029\u0045\u002e\u004f\u002a\u0061\u0062\u0045\u0038\u003b\u0071\u0069\u0030\u005d\u006d\u0030\u0052\u0034\u0069\u004c\u002c\u0079\u0030\u0046\u0078\u0054\u004d\u007c\u0057\u0044\u0026\u0028\u0037\u002a\u006c\u0055\u0054\u0078\u002a\u007b\u005d\u004f\u0053\u0069\u0078\u0033\u0061\u0032\u005d\u003d\u0025\u0043\u0075\u0054\u006d\u0072\u0024\u004b\u0041\u0033\u0048\u003f\u0077\u0078\u0061\u002c\u0052\u006a\u004e\u006e\u0045\u0041\u002c\u0070\u0035\u003a\u004b\u0033\u0060\u0069\u0042\u007d\u0040\u003a\u0079\u0069\u0053\u0064\u0051\u007c\u0021\u002e\u0066\u004b\u002e\u0022\u0041\u0079\u0069\u0050\u0067\u0051\u0067\u006d\u0049\u0049\u0077\u0054\u004e\u0041\u0060\u0055\u0022\u0078\u0060\u004c\u0078\u0042\u0041\u002f\u0055\u0058\u0044\u0055\u0044\u004a\u0071\u0066\u0048\u0050\u006f\u005b\u0051\u004e\u0077\u0045\u0041\u002c\u0070\u0065\u007c\u0023\u0045\u0029\u0040\u004c\u0040\u006c\u0028\u0033\u0045\u0044\u0059\u0056\u007b\u002a\u0064\u0051\u0028\u0024\u0041\u007d\u0058\u006e\u007c\u0070\u004d\u002e\u0041\u0060\u006a\u002c\u0056\u0038\u002e\u0053\u0028\u002b\u0055\u0058\u0043\u0046\u006e\u0066\u002a\u007d\u0053\u005b\u0034\u007c\u005a\u003a\u0032\u0060\u0053\u004e\u007b\u0033\u0058\u006e\u002c\u0070\u002a\u0064\u0032\u004f\u0079\u0029\u0021\u006b\u004c\u0041\u004b\u0050\u002e\u0067\u0058\u0033\u0054\u0048\u0031\u0055\u0047\u006b\u006e\u0049\u0072\u0065\u0039\u006c\u006e\u0032\u0062\u0030\u007d\u0049\u0055\u0045\u005d\u0029\u006e\u0034\u0021\u004c\u0069\u0062\u0033\u0061\u0029\u0050\u0064\u003a\u0071\u004a\u0022\u0059\u0053\u0022\u0021\u0073\u0053\u0033\u0046\u0023\u006f\u006a\u0069\u0038\u0067\u0059\u0033\u0079\u006c\u004f\u0041\u0028\u0050\u0036\u0048\u004f\u0033\u007c\u0077\u007b\u003b\u0067\u006d\u004f\u0041\u0028\u0050\u0036\u0048\u0075\u0045\u0072\u0025\u006f\u002e\u0051\u0024\u004e\u007b\u0026\u0044\u0032\u0045\u0067\u0035\u0040\u0068\u0062\u007b\u0071\u0047\u004a\u002e\u0045\u0078\u004e\u007b\u0026\u0044\u0032\u0045\u004e\u002c\u0029\u0044\u0074\u0068\u0025\u0043\u007a\u0045\u004c\u006d\u0063\u0044\u0058\u002c\u0031\u0048\u0072\u0055\u002e\u0073\u007c\u006e\u0071\u007c\u0059\u002c\u002a\u0062\u0062\u0075\u0061\u004d\u0076\u0051\u0026\u0044\u0032\u0045\u004e\u002c\u0058\u0037\u0050\u003b\u0071\u0023\u0055\u0046\u0057\u007d\u006d\u0039\u0024\u0079\u0076\u0073\u002b\u0060\u003a\u002a\u005d\u006e\u0030\u0075\u0024\u004e\u0032\u007a\u0038\u0042\u007d\u002f\u0037\u0038\u007a\u006a\u003a\u007a\u0045\u004c\u006d\u0063\u0044\u0035\u0035\u0056\u006a\u0068\u0038\u0054\u0059\u0041\u0054\u0078\u0060\u0056\u006d\u0057\u0050\u0064\u002c\u0022\u006b\u0056\u006e\u0026\u0050\u007d\u006d\u0039\u0043\u0049\u004b\u003d\u002e\u0050\u002a\u0076\u0056\u003e\u0065\u0065\u0056\u007a\u007e\u0049\u0061\u007c\u0059\u002c\u0021\u0035\u006c\u0074\u0032\u0056\u0031\u0023\u0050\u0075\u0049\u0061\u007c\u0059\u002b\u003f\u0067\u004a\u0033\u0025\u0075\u0066\u0029\u004a\u0075\u0032\u0048\u0060\u0033\u0022\u003c\u005d\u0059\u0038\u006b\u007c\u0043\u004e\u0057\u0043\u006d\u003a\u004f\u0040\u0036\u0060\u0063\u0058\u0021\u0023\u0041\u0067\u004e\u0025\u0054\u0059\u0036\u004e\u0072\u0057\u0046\u0062\u0044\u007e\u0061\u0059\u002b\u0059\u006e\u0044\u005a\u0044\u0061\u0071\u005d\u002a\u0071\u003a\u0044\u0052\u0029\u0075\u0055\u0043\u0028\u0034\u0034\u0067\u0073\u003b\u003c\u005a\u0070\u003b\u0066\u006c\u004d\u002c\u006e\u0028\u0042\u004d\u003e\u0074\u004c\u0032\u004b\u0051\u0064\u0065\u0066\u0029\u007a\u0042\u0071\u007d\u0079\u0029\u0046\u0029\u0043\u0050\u0076\u0037\u0030\u003f\u0043\u0047\u0030\u0039\u004e\u007c\u0054\u0024\u0049\u0076\u0054\u0045\u007e\u0036\u0033\u006b\u0064\u0069\u0029\u0064\u0051\u0060\u0029\u0039\u0023\u0042\u0023\u0040\u0074\u0043\u005d\u0070\u0041\u0055\u006b\u0044\u004f\u0025\u006f\u003b\u0042\u007e\u006b\u005a\u0025\u007e\u007d\u0035\u0079\u0035\u0024\u006a\u0078\u005b\u0044\u0077\u0065\u0076\u0071\u0065\u006d\u0034\u0064\u006a\u0078\u005b\u0044\u0035\u0073\u006c\u0059\u002e\u0068\u0060\u006a\u0022\u005a\u0060\u002c\u006f\u0062\u0058\u0063\u007d\u003b\u0079\u0061\u004d\u005d\u007e\u0056\u0053\u005a\u004c\u003a\u0077\u0075\u004f\u0047\u002c\u003d\u006e\u007d\u003a\u0029\u0063\u0024\u0076\u007a\u002f\u002b\u0074\u0078\u0079\u0034\u006b\u002a\u0023\u0050\u0068\u0033\u0057\u0044\u0060\u0038\u005b\u0072\u002c\u003b\u006a\u004f\u003c\u006a\u007d\u005a\u002f\u0077\u003a\u0064\u0038\u0047\u0065\u0026\u007d\u005a\u0075\u002c\u0030\u0067\u0056\u003a\u0064\u0021\u005b\u006e\u0021\u003c\u005a\u0067\u0023\u0074\u0028\u0028\u0053\u0040\u003c\u003b\u0079\u0048\u006a\u0025\u005e\u0071\u003f\u0062\u0021\u0050\u007a\u003a\u005b\u0079\u0021\u0025\u0039\u0062\u007a\u0060\u0065\u0072\u0047\u004a\u0078\u0078\u0037\u0072\u004b\u0033\u0040\u003a\u0075\u0025\u006b\u006b\u005e\u004e\u0057\u002b\u0067\u007b\u002b\u003b\u002c\u003a\u0038\u0045\u0047\u0022\u0047\u007a\u0074\u006e\u002c\u0065\u0025\u0061\u0064\u0032\u0056\u007b\u002f\u005a\u0071\u0032\u002b\u0034\u0024\u003f\u005b\u0043\u004b\u0033\u0040\u003a\u0075\u0025\u0059\u005d\u003f\u006e\u0033\u0058\u006b\u0054\u007b\u0054\u0029\u0060\u0069\u0062\u006e\u0060\u0047\u007a\u0048\u0040\u0062\u0071\u0049\u0063\u0052\u003f\u005f\u0068\u0044\u0069\u0061\u0026\u003e\u004d\u0024\u006a\u0047\u0066\u0049\u0049\u0038\u0024\u004f\u004d\u0065\u0049\u0061\u006f\u0070\u003f\u0060\u0068\u0023\u0023\u0077\u004c\u005a\u0060\u0030\u0044\u005f\u0029\u0029\u007d\u0033\u0045\u0057\u004d\u0024\u006a\u004f\u0079\u0021\u0038\u004d\u003a\u0035\u0055\u0060\u0078\u004c\u0042\u005f\u0033\u007d\u0024\u0040\u0062\u0040\u0021\u0065\u004c\u0075\u0071\u0077\u0061\u0031\u004c\u007e\u002c\u0028\u005e\u0047\u0023\u0055\u003a\u007c\u003a\u0066\u0042\u0061\u0040\u0049\u0035\u0074\u004b\u0047\u004c\u005a\u0031\u007a\u0074\u0052\u0060\u0060\u0040\u0058\u0039\u0035\u0060\u0069\u006b\u0037\u004c\u0061\u0053\u0068\u003b\u0038\u0075\u007e\u003e\u004b\u004f\u005f\u0045\u007d\u005a\u003d\u0051\u0037\u0069\u0070\u0023\u0070\u0044\u006a\u0059\u0026\u0060\u003d\u0025\u0028\u0023\u0058\u0077\u0025\u007d\u0040\u003a\u0058\u005b\u0051\u005a\u0021\u0072\u003a\u004c\u0031\u0033\u0021\u0031\u005a\u002b\u002f\u0056\u0022\u0041\u0038\u0073\u0058\u007a\u0045\u0053\u0049\u0033\u0062\u0040\u004b\u005e\u0038\u004c\u0069\u007d\u0076\u006b\u0063\u0062\u005f\u0044\u002c\u0072\u004a\u0076\u0059\u0068\u006a\u004f\u0068\u0077\u004c\u002f\u006d\u0065\u0045\u004e\u0058\u0046\u0046\u0043\u007a\u0041\u0063\u0054\u007a\u0075\u0049\u0038\u003f\u0050\u006a\u0079\u0050\u007c\u0079\u0062\u007a\u0033\u004a\u007b\u002b\u0061\u0059\u0079\u006c\u0034\u0074\u006c\u0072\u0063\u006e\u0070\u002e\u0056\u0028\u0034\u005f\u0075\u0078\u0063\u002b\u0045\u0032\u005b\u0077\u004c\u002e\u004e\u0056\u003a\u0078\u007b\u0076\u0029\u0034\u004e\u005b\u006d\u007a\u0047\u0074\u005f\u004f\u0048\u0056\u007a\u0050\u006e\u005d\u0051\u0055\u003b\u0050\u0023\u0063\u002c\u0041\u0070\u0041\u004b\u006a\u003b\u0065\u006a\u003c\u0026\u0040\u005f\u0039\u0076\u005f\u003b\u0050\u0063\u004f\u0032\u0064\u006c\u0023\u004b\u006d\u0072\u003e\u0071\u0035\u0037\u0046\u0075\u004c\u0037\u0038\u007b\u0065\u005d\u0043\u0071\u005e\u0037\u0077\u0069\u002e\u002c\u0053\u0074\u0048\u007c\u0030\u005b\u0037\u0052\u004a\u0046\u004c\u004c\u006f\u002e\u0036\u0078\u0069\u0073\u003a\u006f\u002b\u0034\u0047\u0075\u0071\u004f\u0066\u0053\u004e\u0026\u004b\u0076\u007b\u002f\u002f\u0055\u003e\u0040\u004f\u006e\u005b\u004b\u006b\u004f\u0059\u0036\u0033\u0041\u003c\u0068\u0060\u004e\u0033\u0036\u0060\u004e\u0075\u0032\u0037\u0042\u0046\u006d\u0029\u003e\u003c\u0035\u002e\u006b\u002a\u0024\u0022\u0031\u005a\u005b\u004e\u0075\u005d\u004d\u006c\u007c\u0055\u0036\u0035\u006c\u0076\u0035\u0061\u002a\u002c\u004a\u0076\u0055\u002f\u0042\u003a\u004b\u002e\u0056\u0060\u0067\u006f\u0046\u0076\u0070\u002e\u007e\u005f\u0064\u003b\u0062\u0026\u005a\u0052\u0065\u003a\u0029\u002f\u0071\u003a\u0071\u0060\u0052\u007e\u0046\u002c\u0033\u0026\u0045\u0064\u0056\u007b\u0058\u0033\u0073\u0047\u0044\u0069\u004a\u0046\u003d\u007e\u0063\u0061\u004e\u0072\u0065\u004f\u0071\u0067\u0068\u0051\u0059\u0035\u006c\u0072\u0030\u0076\u003d\u0075\u0029\u007b\u0076\u0029\u0032\u0056\u006d\u0067\u007d\u006b\u0047\u005d\u0053\u0033\u0075\u006d\u006a\u004d\u005a\u002c\u003f\u0074\u007c\u0079\u0075\u0036\u004c\u0043\u0059\u0075\u003e\u0073\u006a\u004c\u003d\u0042\u0072\u007d\u0022\u002f\u0030\u0057\u003e\u007b\u007e\u0045\u0043\u007e\u0063\u0061\u0067\u0035\u0072\u0025\u0049\u0075\u0079\u005e\u0040\u0043\u0024\u003c\u0023\u0046\u0029\u004e\u0051\u0058\u0057\u007b\u0076\u0055\u0064\u004c\u0029\u004e\u0058\u002e\u0079\u0024\u003c\u0043\u0079\u0070\u004e\u0042\u002c\u003a\u005f\u0057\u006e\u0050\u0056\u0030\u0046\u0029\u004e\u004e\u0073\u0076\u0069\u007a\u004a\u002c\u0068\u0034\u0030\u004b\u0036\u003e\u0065\u0062\u0028\u0039\u0025\u006e\u0022\u007d\u0035\u002c\u004a\u0076\u0055\u002f\u0042\u003a\u004b\u002e\u0056\u0060\u0067\u006f\u0046\u0076\u0070\u002e\u007e\u005f\u0064\u003b\u0062\u0026\u005a\u0061\u005d\u003b\u0061\u005d\u0070\u0075\u0052\u002c\u0037\u0036\u0034\u0042\u0069\u004e\u003b\u006a\u003a\u003f\u006c\u0038\u002a\u004d\u0067\u0061\u0072\u005a\u0068\u004d\u003e\u0037\u0046\u002a\u0041\u0033\u004c\u0033\u0024\u003c\u0054\u0062\u0066\u007c\u0024\u0040\u0026\u0061\u0023\u0024\u0031\u007a\u0077\u003a\u0030\u0063\u0042\u006e\u003c\u005f\u0040\u004a\u0041\u003a\u0042\u004b\u0070\u0043\u0074\u0025\u0060\u0064\u0030\u004c\u0068\u003f\u0068\u0031\u003f\u007c\u004e\u0065\u0059\u0021\u005f\u0064\u0045\u0051\u0033\u007a\u0046\u004e\u004e\u005b\u002b\u0078\u0076\u0074\u0053\u0064\u0023\u0066\u005a\u0024\u0051\u006b\u003f\u0061\u0026\u0079\u004c\u0037\u0050\u004f\u0067\u006e\u006e\u0062\u0071\u0052\u0067\u0028\u003c\u0058\u003e\u0052\u0076\u0063\u0048\u0042\u0046\u007c\u0072\u004f\u0076\u0066\u0025\u003e\u002e\u0041\u0074\u0026\u0029\u007c\u003e\u0029\u0036\u0068\u004f\u007b\u0023\u0037\u007d\u0036\u0077\u007b\u0067\u0059\u0046\u0049\u0032\u0075\u0078\u0064\u0028\u0030\u004d\u003b\u004e\u002f\u0037\u0049\u0038\u003b\u0058\u0021\u006f\u006b\u0067\u005a\u0079\u0047\u0063\u004f\u0028\u0074\u0062\u0026\u004b\u003a\u002c\u0048\u005b\u0024\u003d\u0024\u0067\u0046\u0039\u0021\u0028\u0062\u006a\u005d\u0076\u0039\u0046\u0033\u0072\u006b\u0025\u0078\u007d\u003c\u0072\u002e\u0043\u0066\u004d\u003f\u0053\u003f\u003d\u0021\u0032\u0059\u0021\u002f\u004a\u0034\u0072\u002e\u004e\u0071\u0051\u0074\u0043\u002a\u0069\u0077\u007e\u0076\u002b\u002b\u004b\u005a\u0021\u0028\u0074\u003e\u007e\u0064\u0052\u0021\u003b\u003e\u0068\u0058\u0066\u002a\u0071\u004a\u0069\u0058\u0023\u005d\u0061\u006a\u0057\u0030\u004f\u0028\u0071\u0034\u002e\u0073\u007d\u0028\u002b\u0069\u005d\u005b\u0032\u006c\u0062\u0032\u006a\u0051\u0055\u0055\u007d\u0053\u0063\u0038\u002c\u0071\u0050\u0054\u0036\u002c\u0046\u0045\u004c\u0077\u002e\u002e\u005e\u002f\u0052\u006b\u003e\u007e\u0069\u004f\u0033\u0045\u007a\u0075\u003a\u0062\u003c\u0056\u004c\u0079\u0032\u0075\u003f\u006f\u0032\u0025\u0066\u0028\u0031\u0024\u0022\u0021\u007b\u0039\u0040\u0025\u003e\u0073\u0074\u006d\u003b\u006f\u007d\u003a\u0067\u0030\u004e\u0035\u007e\u0021\u0074\u0045\u002e\u006b\u0062\u004a\u0040\u0031\u0060\u0072\u0058\u0078\u0067\u004a\u003a\u005d\u003e\u006f\u0038\u004c\u002a\u0051\u0026\u0025\u0025\u0039\u005b\u005a\u0035\u0041\u006c\u004a\u003b\u006a\u0073\u0051\u0074\u0045\u0055\u0025\u004e\u0078\u0061\u002a\u0061\u0065\u0065\u0041\u0044\u0072\u003b\u0075\u006b\u0069\u003a\u0035\u0025\u0028\u0030\u003b\u0075\u0026\u004a\u0029\u0041\u0062\u007e\u002b\u007b\u002c\u0056\u0029\u005b\u0023\u0073\u003c\u0063\u0077\u0032\u0026\u007c\u0035\u005e\u007d\u0024\u005b\u0076\u0047\u006e\u0056\u0045\u0057\u0077\u0030\u0077\u0051\u0050\u0054\u007e\u0049\u0037\u003a\u0056\u0036\u0068\u0079\u0030\u005e\u0025\u0070\u0053\u007e\u0064\u0065\u0057\u002b\u004f\u006a\u0079\u0039\u0024\u0031\u0043\u005d\u003c\u0077\u0024\u0024\u0050\u004c\u006b\u0067\u003b\u0069\u006b\u003a\u002f\u0077\u0054\u0067\u005e\u005d\u0051\u004a\u0075\u007b\u0033\u0054\u0057\u0072\u0073\u0066\u0069\u0032\u0021\u005d\u004b\u005b\u006b\u003e\u007e\u006d\u0054\u0051\u002b\u0064\u0026\u0024\u0049\u0055\u007e\u0079\u0048\u007d\u0045\u0050\u0074\u0022\u006c\u006a\u0066\u0054\u007e\u0035\u0033\u0075\u005d\u0075\u005a\u002e\u003a\u0033\u0063\u0054\u0067\u0079\u0057\u0033\u0025\u0073\u0069\u0029\u004e\u004f\u006e\u007c\u0079\u0055\u0053\u0041\u003f\u002c\u0052\u0059\u0029\u0035\u0038\u0072\u0064\u0076\u0067\u0037\u0044\u0025\u0070\u003e\u004b\u0060\u0022\u0038\u007e\u0055\u0041\u007d\u004e\u0076\u0051\u0059\u0031\u007e\u0055\u007e\u0051\u0050\u0077\u007e\u005d\u003c\u006a\u004b\u005b\u002c\u0035\u0034\u0021\u0056\u0071\u0022\u005f\u007b\u0033\u004e\u0024\u0044\u0074\u0043\u0069\u002f\u0021\u003a\u004f\u0054\u0032\u0022\u004b\u0061\u0070\u007b\u004b\u003d\u0051\u0055\u006f\u0060\u0032\u0073\u004c\u0071\u0033\u0040\u003c\u0028\u0034\u006c\u007e\u0036\u0063\u0055\u002f\u0066\u0042\u0033\u0030\u0065\u0041\u006e\u0049\u007e\u0073\u007e\u0079\u0024\u003f\u007e\u0054\u007e\u005d\u003c\u0041\u0065\u0035\u0026\u006b\u006a\u0078\u0036\u0051\u002e\u0068\u0061\u003c\u0031\u004c\u0052\u0077\u0050\u002f\u006e\u0033\u002c\u0026\u0045\u0045\u003b\u0051\u0035\u0031\u0045\u003f\u0023\u0037\u0050\u003c\u0046\u007d\u0047\u006a\u004d\u004e\u0056\u002b\u0052\u0066\u007e\u002a\u0047\u0047\u003a\u0058\u0065\u0046\u0075\u006d\u0024\u0073\u005e\u0078\u0045\u0053\u006a\u0026\u0071\u0022\u0033\u006a\u0044\u003b\u0038\u0051\u006c\u0070\u005d\u0069\u002f\u0071\u0056\u0022\u0055\u003c\u0065\u005b\u0056\u0065\u0076\u0036\u003d\u0028\u004b\u005d\u0021\u0063\u0030\u0058\u0049\u0044\u0031\u005b\u0048\u0065\u0053\u002b\u0062\u0062\u0062\u0021\u0054\u0049\u0042\u005e\u004b\u0055\u006d\u0076\u007a\u0056\u0071\u004e\u0065\u0074\u0073\u005a\u0032\u0077\u0031\u0046\u0023\u0057\u0054\u0043\u0033\u0061\u007a\u007a\u007b\u002c\u005d\u005e\u003d\u002c\u0076\u0034\u004f\u0051\u0055\u0073\u005b\u0055\u0031\u005b\u004e\u0061\u007a\u007b\u0045\u0041\u0021\u0065\u0026\u0040\u007c\u005a\u007a\u003c\u0076\u0026\u002b\u002c\u004f\u0073\u0058\u0041\u0043\u0071\u0057\u006c\u0023\u0077\u007c\u0056\u0054\u0040\u0033\u005e\u007b\u0023\u0062\u0063\u0071\u0062\u0029\u0055\u0072\u0044\u005f\u002f\u003f\u0036\u004e\u005e\u0025\u005f\u0078\u0053\u006c\u004d\u0034\u0077\u0036\u0052\u0040\u0056\u0030\u0056\u0068\u0059\u003e\u0071\u0059\u0071\u002c\u0039\u0024\u0043\u0079\u0039\u0066\u0040\u0053\u0038\u0075\u007e\u0054\u0048\u0069\u0044\u0028\u0042\u0028\u0039\u0062\u0049\u0043\u0059\u0050\u0036\u006f\u005a\u005e\u0030\u0054\u0030\u0037\u002c\u007e\u004d\u0043\u005d\u0043\u0074\u0028\u0076\u0039\u0067\u002b\u0078\u0057\u005e\u0063\u005b\u0076\u0037\u0021\u006e\u0057\u005e\u006f\u0037\u0024\u002c\u0022\u003a\u0033\u0043\u0069\u0055\u0023\u0032\u0055\u004a\u0021\u0047\u0040\u0048\u0043\u004e\u0026\u0060\u006d\u0049\u0050\u006e\u0030\u0058\u002c\u0040\u0026\u0060\u006d\u0049\u0025\u0067\u0030\u004f\u0038\u003c\u0061\u0026\u0065\u0055\u0061\u0078\u0068\u007b\u0032\u0062\u0071\u006f\u003c\u0048\u0069\u006c\u0043\u0031\u0024\u0055\u0035\u0060\u0022\u0052\u0037\u004b\u003c\u0053\u0033\u0066\u0043\u0023\u0026\u0045\u0066\u0048\u0072\u002e\u0070\u0046\u0061\u002b\u0077\u0057\u0069\u0032\u0057\u002b\u0077\u0021\u0078\u003f\u0059\u0045\u006d\u006f\u004f\u0040\u007a\u007d\u0068\u0029\u0069\u0029\u0055\u0064\u0036\u005d\u003d\u006a\u0038\u004b\u0058\u002c\u0050\u0054\u005a\u0022\u0061\u007b\u006b\u004e\u0074\u004d\u0076\u006b\u0067\u0077\u0025\u0056\u006b\u0072\u0061\u002f\u007e\u0021\u0074\u0059\u004c\u0073\u0056\u002b\u0062\u0050\u0039\u0067\u003c\u0045\u0060\u0029\u0053\u003c\u0074\u0055\u004f\u004f\u0022\u0069\u0024\u005a\u0022\u0038\u003c\u004e\u0026\u006c\u002a\u0055\u0070\u004c\u0052\u0023\u0052\u0048\u006e\u004e\u0032\u004b\u0029\u0069\u004e\u0055\u0022\u007a\u0076\u005b\u0034\u0076\u004c\u0070\u0073\u0050\u002c\u003c\u0079\u002f\u003b\u0066\u0073\u0064\u0071\u0051\u005b\u0036\u005a\u0079\u002a\u002f\u0021\u0023\u0069\u005f\u0074\u004d\u0044\u005b\u0065\u0024\u005d\u0058\u0024\u005d\u0030\u005a\u003d\u0034\u0075\u0073\u005e\u0050\u006f\u0024\u006b\u0026\u0079\u0024\u0029\u0041\u0036\u0070\u0045\u002e\u0043\u0043\u002b\u005d\u007c\u0029\u0043\u0079\u0044\u0064\u0022\u0074\u0033\u006f\u004f\u002f\u003a\u0041\u0044\u006b\u006e\u004e\u007b\u006d\u0073\u007d\u007d\u006c\u0042\u003f\u002c\u005b\u007b\u004c\u0057\u0068\u004f\u0041\u003d\u0034\u0043\u0037\u0051\u003a\u0072\u0068\u0074\u0021\u005e\u0071\u006b\u0074\u0044\u004a\u0023\u004a\u006e\u0060\u0070\u007e\u0052\u0040\u0059\u002f\u005f\u002b\u0067\u007b\u0023\u0074\u0046\u005f\u0068\u003d\u0077\u0034\u005f\u0066\u0055\u007c\u005e\u0023\u004b\u006e\u007d\u004f\u0058\u0073\u005f\u0066\u0057\u0070\u0060\u0023\u0029\u0061\u006d\u0045\u0063\u0070\u0039\u002f\u003d\u0067\u005e\u0025\u0060\u0079\u0031\u002f\u0074\u007c\u002a\u004d\u0069\u0069\u0069\u004b\u003d\u0028\u006d\u006b\u0031\u0049\u0055\u0041\u003e\u003e\u004e\u0032\u002b\u0050\u0046\u0032\u0072\u0037\u0028\u0029\u0030\u002c\u004f\u0044\u0066\u0048\u0023\u007a\u003d\u006f\u0049\u0047\u0051\u0032\u005b\u0047\u0057\u004e\u003e\u0069\u0023\u007a\u0026\u0050\u006c\u0076\u0062\u004e\u005b\u006a\u003b\u0069\u0054\u0068\u0023\u0063\u0033\u004c\u005a\u0032\u0029\u0067\u0028\u006e\u0037\u0028\u0069\u0044\u0074\u003f\u0034\u003d\u0064\u003c\u005a\u0071\u006f\u0045\u0070\u0069\u005a\u006a\u005b\u003a\u0067\u0053\u0064\u0023\u003f\u0038\u003f\u0034\u0053\u0052\u006d\u007b\u0025\u0024\u0050\u0044\u0069\u003c\u0049\u004d\u0057\u006d\u0065\u006e\u004d\u0069\u003e\u003f\u0046\u0032\u005a\u0054\u0030\u0037\u0048\u0037\u0067\u006a\u0047\u0061\u006a\u002b\u0054\u0063\u002a\u0055\u004b\u0034\u0036\u0034\u0071\u0040\u0029\u0022\u0061\u0023\u0070\u0065\u0025\u0034\u0071\u0056\u0077\u0042\u0037\u0063\u006b\u005a\u0043\u0059\u0049\u0026\u004f\u003b\u0055\u0070\u0072\u0048\u0070\u004b\u0035\u0063\u006e\u0041\u004e\u003c\u0036\u003f\u0031\u0057\u006d\u007c\u004f\u0079\u006a\u0039\u0038\u007d\u003a\u0056\u0055\u006a\u0057\u003c\u0050\u0051\u0058\u0021\u0039\u0059\u0028\u003e\u0033\u006e\u0058\u007d\u0041\u005a\u0067\u006a\u0024\u0074\u0045\u007d\u007a\u0067\u0074\u004a\u007c\u006e\u0037\u0039\u0034\u0073\u004f\u0056\u0058\u0022\u002b\u003c\u0077\u0068\u004b\u002c\u0026\u0078\u0072\u0029\u006c\u003a\u0071\u003d\u0075\u007a\u0047\u007c\u0026\u005e\u0066\u006b\u0022\u0039\u0064\u0034\u0033\u002c\u0060\u003f\u002c\u0075\u0068\u0071\u0054\u003f\u004a\u004c\u0023\u0055\u006c\u0062\u003e\u005e\u0056\u0042\u005e\u007e\u004d\u006f\u005a\u004b\u0034\u0037\u0061\u003f\u0033\u002e\u007c\u0046\u0024\u003d\u0041\u003e\u0022\u0066\u0037\u0045\u0032\u0031\u0060\u0077\u0040\u0040\u0063\u0048\u007c\u0061\u0032\u0031\u0060\u0077\u003c\u002b\u007c\u0034\u0032\u003f\u003d\u0034\u005e\u0066\u004e\u006a\u0038\u006c\u0047\u0054\u006d\u0026\u006e\u0035\u0046\u003b\u0033\u003d\u0067\u0031\u0056\u0052\u0053\u005f\u0023\u005f\u0036\u0051\u0039\u0040\u005a\u0042\u005d\u0031\u0058\u0022\u005b\u0075\u0048\u002a\u0026\u0023\u0051\u006b\u0052\u004b\u0029\u003b\u002a\u0026\u0054\u0032\u002f\u006e\u0042\u007b\u0037\u004f\u003e\u004c\u0070\u004e\u0033\u0072\u0033\u0053\u0024\u002b\u0021\u0067\u0038\u0058\u0043\u0025\u007a\u006f\u0055\u0074\u0057\u0048\u0073\u0078\u0030\u005b\u0052\u0068\u0078\u0044\u0026\u003d\u0031\u0078\u0047\u0048\u006c\u0077\u007e\u0042\u004f\u006f\u0033\u0069\u0039\u0058\u007d\u0030\u005b\u0033\u0039\u004c\u0041\u003b\u006a\u0059\u005d\u003c\u007a\u0033\u0078\u0039\u0053\u0058\u0033\u004d\u0062\u005b\u0053\u004f\u004f\u0057\u0072\u0022\u005f\u006a\u005d\u005a\u0023\u003c\u0053\u0063\u007d\u0067\u0062\u0057\u003e\u007a\u0069\u003e\u0033\u0072\u0030\u0053\u0057\u006a\u002c\u0055\u0064\u0053\u007a\u007e\u002e\u0068\u007d\u0063\u006d\u006f\u007a\u0062\u0061\u005b\u003f\u004b\u0040\u0041\u0034\u0057\u006e\u0065\u005e\u0068\u004a\u005a\u0049\u003e\u0072\u0070\u0068\u0024\u0052\u0026\u0053\u003e\u0053\u0078\u003a\u0033\u003b\u0068\u005a\u0062\u0029\u007d\u0074\u0029\u0056\u007b\u0038\u004d\u007d\u0028\u0068\u0068\u0056\u0076\u0040\u0059\u005d\u007d\u0072\u0034\u0036\u0030\u0021\u004d\u0062\u007b\u0077\u0078\u006f\u0057\u0071\u0035\u0074\u0029\u0056\u007b\u0038\u004d\u005a\u0062\u0079\u006f\u0058\u0069\u0048\u0038\u007e\u0051\u006f\u006f\u006d\u0031\u0068\u006d\u0034\u003f\u006c\u0032\u0079\u0052\u007e\u005a\u0062\u0040\u0025\u0042\u0060\u0025\u0063\u002a\u0032\u0038\u0058\u0079\u007b\u0054\u0039\u0070\u006d\u0071\u0032\u0042\u003e\u007c\u006b\u0064\u0074\u0067\u002e\u0041\u006d\u0034\u006f\u0037\u0043\u0048\u0042\u004e\u004f\u0068\u0033\u0065\u002b\u0063\u0042\u0026\u003d\u002c\u0039\u0039\u002a\u0021\u002c\u0033\u0039\u0079\u0071\u0024\u0057\u005b\u0046\u0037\u0045\u0024\u0067\u004b\u0078\u004a\u0030\u0073\u007b\u006d\u0075\u0062\u006f\u0025\u002b\u006e\u004f\u0065\u0067\u002e\u0039\u0061\u007e\u002e\u0065\u0054\u007e\u0075\u002a\u0069\u0021\u0056\u0035\u0062\u0031\u0023\u0073\u0042\u002b\u0030\u006f\u0075\u006c\u007b\u0034\u006d\u002f\u0075\u006d\u0051\u0021\u004a\u003c\u0042\u0064\u0041\u007c\u0045\u005f\u0062\u0065\u0055\u002f\u0031\u0037\u007d\u0074\u0042\u0050\u0063\u0045\u006c\u0067\u0044\u0034\u0073\u0057\u0044\u0041\u004d\u0041\u0060\u005b\u003e\u0039\u0073\u003f\u0029\u004d\u0021\u004c\u006f\u0037\u0071\u005b\u007a\u0076\u0045\u0045\u0061\u0062\u006b\u0068\u0022\u0062\u0024\u007b\u003f\u0026\u0067\u0038\u0032\u0067\u003c\u0032\u005a\u0062\u004c\u007d\u0049\u007e\u0060\u002a\u004c\u0038\u002b\u0028\u0040\u003d\u002e\u007a\u007d\u0066\u0068\u0060\u006f\u004a\u0063\u007e\u005e\u0075\u0055\u007a\u006f\u002e\u0044\u0025\u0039\u0053\u0079\u0056\u0037\u0073\u0060\u0061\u0073\u0039\u004f\u0029\u006d\u0035\u0049\u002f\u0071\u0026\u0070\u0053\u0055\u0036\u0048\u0056\u0074\u006b\u006e\u005b\u0038\u0051\u002e\u0056\u0071\u0067\u0074\u007a\u003f\u003f\u0073\u0038\u002a\u0050\u004a\u0038\u0023\u002c\u0021\u006d\u0061\u0056\u004b\u0034\u003b\u0062\u0053\u0038\u0070\u0034\u002b\u006d\u0067\u0067\u005b\u0046\u0069\u0031\u0069\u007b\u0032\u0057\u0046\u0032\u003b\u004e\u0051\u005e\u0073\u0056\u007e\u0064\u0041\u0054\u0053\u006c\u0059\u005e\u007c\u0057\u005d\u0046\u002e\u002a\u0070\u002e\u003b\u0033\u0061\u007c\u002c\u004a\u0070\u007b\u005f\u007a\u0064\u0033\u0051\u0039\u0038\u0021\u003e\u007a\u0050\u0075\u0051\u004a\u005d\u004c\u0066\u003d\u0047\u0033\u006e\u003d\u003c\u0034\u0023\u003a\u0021\u004d\u0070\u0024\u0062\u003a\u0044\u004f\u0055\u0022\u0079\u0042\u0041\u004c\u004b\u0065\u007d\u0031\u0047\u006f\u0035\u0042\u0041\u004c\u004b\u0033\u005f\u004a\u0077\u0053\u0042\u007d\u0070\u0053\u0068\u0047\u0051\u002c\u005e\u0062\u004d\u0031\u0023\u0074\u003e\u0046\u0021\u004e\u0070\u004f\u0041\u0073\u0054\u003e\u0066\u0079\u006c\u0078\u0058\u0062\u0053\u0070\u005d\u0035\u0025\u0050\u0078\u003e\u007a\u004e\u0057\u006e\u0056\u0055\u007b\u0060\u002f\u0057\u006e\u0069\u007e\u0050\u0030\u0035\u0034\u0028\u0023\u0041\u002e\u0063\u0065\u0045\u003f\u0045\u006c\u0078\u003a\u0055\u0049\u007b\u007c\u0026\u0022\u006b\u0056\u004c\u0074\u0029\u004e\u0025\u0043\u0044\u0077\u0042\u005b\u0043\u0024\u006e\u0031\u0073\u0043\u0072\u004e\u0067\u0051\u004a\u005f\u0067\u003d\u0035\u0076\u0033\u007c\u0057\u007c\u003e\u0045\u0026\u0051\u004f\u0053\u0078\u0047\u007e\u007e\u0048\u0064\u0063\u005b\u007c\u0049\u0055\u0061\u004c\u0045\u0058\u0068\u0077\u006c\u0023\u0023\u0029\u003f\u006e\u0037\u0030\u007b\u002f\u007d\u0021\u0047\u005d\u005f\u0059\u006c\u0048\u003c\u0049\u0068\u0048\u0030\u0035\u0045\u003f\u0044\u006c\u0029\u002b\u0046\u002c\u006d\u0021\u0021\u005b\u003c\u0048\u005e\u0056\u006b\u0068\u0033\u0067\u0042\u0032\u0046\u004c\u0058\u005d\u004f\u0035\u002a\u0050\u0030\u0064\u003a\u0038\u0064\u0059\u007b\u0023\u0058\u002f\u003b\u006c\u0032\u0021\u005e\u0049\u0064\u0024\u0042\u007d\u005b\u0060\u0055\u006d\u0074\u0049\u0021\u0071\u005e\u0071\u0064\u007a\u0051\u0068\u0045\u003b\u0053\u0052\u0045\u003b\u003a\u0048\u0035\u0046\u005e\u003f\u003e\u0053\u0053\u0057\u0055\u004b\u0045\u0053\u0036\u0066\u0078\u0029\u0077\u004f\u0028\u0070\u003a\u0051\u0032\u0043\u0061\u0044\u0025\u0034\u005e\u0063\u0063\u005f\u0037\u006e\u0060\u0023\u003b\u0049\u0021\u0053\u003e\u004d\u004d\u007a\u0057\u0039\u0055\u002b\u0033\u0068\u0048\u0051\u0060\u002f\u0033\u0054\u0071\u0061\u005b\u0029\u003e\u0037\u0068\u0075\u0079\u004a\u0048\u003a\u0074\u006c\u0042\u005b\u0031\u0063\u0040\u007a\u0068\u0063\u0023\u002e\u0038\u005b\u0031\u0074\u003c\u0075\u0068\u0051\u0035\u0075\u0048\u003d\u0067\u0049\u0024\u0064\u003f\u0041\u0053\u0025\u0047\u0039\u006a\u0030\u004c\u007e\u0044\u0059\u0068\u006b\u0029\u0029\u0022\u007d\u0071\u0049\u005b\u007d\u0069\u0051\u0042\u005d\u0045\u0025\u0039\u0045\u0030\u0039\u0024\u007d\u0074\u0052\u0022\u0029\u0047\u0040\u0079\u006e\u0049\u007b\u007c\u0026\u0022\u0069\u003e\u0037\u002c\u0071\u0060\u0022\u0043\u0034\u0074\u0048\u003b\u0028\u0062\u0067\u0068\u0032\u004e\u0032\u006c\u0049\u007d\u006f\u0057\u003c\u0047\u003e\u006d\u003b\u0065\u0077\u005f\u005b\u003b\u0026\u0022\u0026\u002c\u002b\u006e\u0050\u0038\u0053\u0062\u0024\u004d\u0039\u0034\u007e\u0022\u0029\u006b\u0058\u0075\u0072\u007a\u0037\u007e\u007b\u0078\u005d\u007b\u0071\u0029\u004a\u0054\u0075\u0048\u0038\u0042\u0033\u0056\u0051\u006d\u0070\u003b\u005e\u0033\u0028\u0057\u007d\u0067\u0064\u002f\u003e\u0030\u0055\u0064\u0060\u0051\u0032\u007e\u0023\u006f\u0048\u0069\u0078\u005e\u006b\u0033\u0072\u006f\u0039\u0033\u0033\u0069\u0062\u0030\u0075\u0038\u0028\u006a\u0054\u006e\u0041\u007a\u0073\u004c\u0026\u0037\u003e\u0031\u0036\u002e\u0040\u003a\u0056\u0074\u007a\u0033\u0021\u0065\u0029\u0022\u0029\u0028\u007d\u005e\u0067\u003c\u0032\u0044\u0067\u004d\u0024\u0041\u0050\u0024\u0067\u0070\u0065\u0078\u005d\u0051\u0068\u0031\u0036\u004a\u0069\u0056\u006e\u005f\u0053\u0054\u003f\u006f\u0048\u0029\u005b\u0069\u0078\u0039\u006a\u002c\u0064\u0061\u002e\u0022\u0054\u004e\u0063\u002b\u0042\u006c\u0072\u002e\u0045\u005b\u004b\u0064\u0072\u0036\u0021\u004e\u0078\u005d\u0045\u006d\u0074\u0051\u0057\u0045\u0065\u0076\u006e\u0035\u002a\u0068\u005b\u0023\u0063\u0032\u0074\u006b\u007e\u0054\u004b\u0077\u005f\u0068\u0055\u0057\u004d\u0064\u003f\u006f\u004f\u0075\u007a\u003d\u0058\u007b\u004a\u0028\u0031\u0061\u003e\u004a\u005e\u006c\u006a\u0076\u0021\u0040\u0058\u003d\u0045\u0045\u004a\u0028\u0069\u0056\u0073\u0029\u0028\u0043\u0031\u0067\u002b\u005e\u0060\u0029\u0028\u0048\u0060\u0041\u0072\u006e\u0062\u006a\u007d\u0078\u0028\u0062\u0058\u0062\u004d\u0029\u005f\u0075\u004e\u003b\u0064\u0051\u0076\u004b\u0025\u0064\u005b\u006c\u002e\u0071\u0031\u0045\u002f\u0022\u0054\u0044\u0047\u0068\u0053\u0057\u0036\u004c\u0035\u0047\u002c\u0058\u0059\u0072\u0074\u002f\u0068\u0059\u0025\u0056\u0041\u0022\u0033\u005d\u0047\u0065\u003c\u0075\u0058\u0055\u0038\u0060\u0030\u0044\u0050\u002e\u0023\u004a\u0025\u0064\u005b\u006c\u0028\u006c\u0052\u0034\u0046\u0039\u0035\u0071\u0050\u002e\u004b\u004a\u0051\u005d\u005a\u007c\u0041\u0033\u0047\u0024\u0046\u0039\u003d\u0047\u0077\u002e\u0059\u0076\u0046\u005d\u0047\u0065\u0076\u0051\u0021\u0072\u0046\u004f\u003a\u002c\u0069\u0056\u006e\u007b\u0072\u0041\u0074\u0067\u0053\u0022\u0049\u0079\u0034\u005d\u0024\u0057\u0063\u0060\u0071\u0059\u0077\u005d\u0023\u0023\u0049\u0072\u005a\u003d\u0049\u005b\u004a\u0059\u0044\u002e\u0034\u0031\u0077\u0062\u0028\u006e\u003a\u0072\u003e\u0072\u0076\u005a\u004c\u0043\u005a\u0039\u0022\u0048\u0028\u004d\u004e\u0046\u0040\u0068\u004f\u004a\u006d\u003a\u0028\u0041\u004c\u005e\u0043\u0045\u0077\u0044\u0045\u0023\u0067\u003c\u0058\u006b\u0044\u0076\u0076\u0030\u0034\u0051\u007a\u0072\u0038\u0023\u004e\u0040\u007c\u0076\u005a\u002b\u0028\u0075\u003a\u007b\u0032\u006e\u003b\u004d\u0059\u0066\u0023\u0032\u0035\u0054\u005d\u0050\u003a\u007a\u0074\u0050\u0025\u0044\u006e\u005b\u0054\u006f\u0068\u005a\u0066\u0054\u0023\u0053\u0067\u005d\u0056\u003f\u0024\u003a\u0032\u0050\u0074\u0047\u007d\u0039\u0041\u0068\u005b\u0063\u0061\u0043\u007b\u0037\u0039\u0041\u0068\u005b\u0063\u0061\u0049\u004c\u0077\u0046\u0079\u0052\u006e\u0062\u006e\u0031\u0061\u0055\u0057\u0057\u0077\u0048\u0046\u0026\u0073\u0075\u0074\u003b\u0058\u004c\u0063\u0057\u0030\u0040\u0070\u003d\u002b\u003b\u006e\u0046\u0045\u0076\u0024\u0031\u006b\u0043\u0046\u003e\u007c\u0075\u0062\u002f\u002a\u004c\u006d\u004f\u0072\u0073\u0021\u0079\u0079\u006a\u0023\u0052\u0044\u0062\u0031\u0024\u0058\u005e\u0077\u0048\u0024\u0066\u005a\u007b\u0033\u0026\u0079\u0038\u002a\u0033\u007c\u0069\u0025\u006f\u0028\u0032\u007b\u002e\u0036\u007b\u002c\u0045\u007d\u0064\u0026\u004a\u005d\u002b\u0075\u007a\u0043\u0066\u0059\u006b\u002c\u0066\u005b\u0043\u0033\u0023\u005b\u0046\u0073\u0068\u0022\u0050\u0047\u0052\u0068\u002e\u0046\u0074\u0048\u0070\u003c\u0023\u006f\u0066\u0078\u0034\u003a\u0061\u0028\u0079\u0036\u0045\u004a\u0067\u004a\u0024\u0051\u003b\u006f\u0053\u0047\u0054\u006b\u0049\u0059\u0047\u0054\u006e\u004e\u0065\u006c\u003b\u0051\u006e\u002c\u0078\u0032\u003c\u0044\u0028\u0052\u002c\u004d\u0032\u0078\u0068\u0059\u0035\u0057\u007d\u0049\u0040\u0072\u004b\u003c\u0033\u004d\u007e\u004f\u0051\u0058\u0032\u0059\u003f\u002a\u007d\u002c\u0059\u002c\u0066\u002e\u003d\u0051\u0062\u0071\u0051\u007a